import type { Metadata } from 'next';

import { SITE_URL } from './site';

export const SITE_NAME = 'The Volt V';

/** Generated by app/opengraph-image.tsx — the share card for pages without art of their own. */
export const DEFAULT_OG_IMAGE = {
  url: '/opengraph-image',
  width: 1200,
  height: 630,
  alt: `${SITE_NAME} — film, TV, comics, gaming and anime`,
};

/** Stored media is sometimes a path on this site and sometimes a full storage URL. */
export function absoluteUrl(pathOrUrl: string): string {
  if (/^https?:\/\//i.test(pathOrUrl)) return pathOrUrl;
  return `${SITE_URL}${pathOrUrl.startsWith('/') ? '' : '/'}${pathOrUrl}`;
}

/**
 * Next merges metadata shallowly: a page that sets `openGraph` replaces the
 * layout's whole object, dropping siteName, locale and the fallback image.
 * Every page builds its Open Graph block through here so none of it is lost.
 */
export function openGraph(og: NonNullable<Metadata['openGraph']>): Metadata['openGraph'] {
  // `images: undefined` must not wipe out the fallback, so unset keys are dropped.
  const defined = Object.fromEntries(Object.entries(og).filter(([, v]) => v !== undefined));
  return {
    siteName: SITE_NAME,
    locale: 'en_GB',
    images: [DEFAULT_OG_IMAGE],
    ...defined,
  } as Metadata['openGraph'];
}

/**
 * Paginated archives: each page is its own canonical (page 1 has no query
 * string), and page 2+ gets a distinct title so they do not read as duplicates.
 */
export function paginated(basePath: string, page: number, title: string) {
  return {
    title: page > 1 ? `${title} — Page ${page}` : title,
    canonical: page > 1 ? `${basePath}?page=${page}` : basePath,
  };
}

/**
 * Empty archives are thin pages and pages past the end are empty duplicates;
 * both stay crawlable for their links but out of the index.
 */
export function archiveRobots(total: number, page: number, pages: number): Metadata['robots'] {
  return total === 0 || page > pages ? { index: false, follow: true } : undefined;
}

export function parsePage(raw: string | undefined): number {
  return Math.max(1, Number(raw ?? 1) || 1);
}

export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

export function organizationJsonLd(sameAs: string[] = [], logo?: string) {
  return {
    '@type': 'NewsMediaOrganization',
    '@id': `${SITE_URL}/#organization`,
    name: SITE_NAME,
    url: SITE_URL,
    logo: {
      '@type': 'ImageObject',
      url: absoluteUrl(logo || '/apple-icon'),
    },
    ...(sameAs.length ? { sameAs } : {}),
  };
}

/**
 * JSON inside a <script> tag ends at the first `</script>`, whatever the JSON
 * says. Titles and bios are user-written, so `<` is escaped to keep a headline
 * from closing the tag and injecting markup.
 */
export function serializeJsonLd(data: unknown): string {
  return JSON.stringify(data).replace(/</g, '\\u003c');
}

/** "Review" → "Reviews", but "News" stays "News" rather than becoming "Newss". */
export function plural(word: string): string {
  return /s$/i.test(word) ? word : `${word}s`;
}
